CREATE PROCEDURE "informix".sp_consdetallesolsupervision(pUsuario CHAR(8), pIdFuncion CHAR(10), pIdConsulta CHAR(1), pNumCliente CHAR(20), pNumSolicitud CHAR(20), 
pFechaInicio DATE, pFechaFin DATE, pStatus CHAR(2), pProducto CHAR(4), pRegistros INTEGER, pRecuperacion INTEGER)
		RETURNING CHAR(5) AS codret,
			CHAR(20) AS num_solicitud,
			CHAR(20) AS num_cliente,
			CHAR(130) AS nombre_cliente,
			DATE AS fecha_solicitud,
			DATE AS fecha_cambio_status,
			CHAR(2) AS status,
			CHAR(8) AS respuesta_os;		

	DEFINE cCodRet CHAR(5);
	DEFINE cCodRetSp CHAR(6);
	DEFINE cDesCodRetSp CHAR(80);
	DEFINE iSqlErr INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE cNumSolicitud CHAR(20);
	DEFINE cNumCliente CHAR(20);
	DEFINE cNombreCliente CHAR(130);
	DEFINE dFechaSolicitud DATE;
	DEFINE dFechaCambioStatus DATE;
	DEFINE cStatus CHAR(2);
	DEFINE cRespuestaOs CHAR(8);	
	DEFINE iRecuperacion INTEGER;

	LET cCodRet = '00000';
	LET cCodRetSp = '';
	LET cDesCodRetSp = '';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET cNumSolicitud = '';
	LET cNumCliente = '';
	LET cNombreCliente = '';
	LET dFechaSolicitud = '';
	LET dFechaCambioStatus = '';
	LET cStatus = '';
	LET cRespuestaOs = '';	
	LET iRecuperacion = 0;

	BEGIN

		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cNumSolicitud, cNumCliente, cNombreCliente, dFechaSolicitud, dFechaCambioStatus, cStatus, cRespuestaOs;
		END EXCEPTION;

		--SET DEBUG FILE TO '/tmp/mfinis/sp_consdetallesolsupervision.out';
		--TRACE ON;

		IF pUsuario = '' OR pIdFuncion = '' OR pIdConsulta = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cNumSolicitud, cNumCliente, cNombreCliente, dFechaSolicitud, dFechaCambioStatus, cStatus, cRespuestaOs;
		END IF;

		-- VALIDACIÓN DE LOS DATOS DE PAGINACIÓN
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, cNumSolicitud, cNumCliente, cNombreCliente, dFechaSolicitud, dFechaCambioStatus, cStatus, cRespuestaOs;
		END IF;


